package dev.mineagent.runtime.core.compile;
import dev.mineagent.runtime.core.packages.NativeCompatibilityPolicy;
import dev.mineagent.runtime.core.task.*;
import org.junit.jupiter.api.Test;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class NativeGenerationContextTest {
    final UUID world=UUID.randomUUID(),task=UUID.randomUUID(),agent=UUID.randomUUID(),owner=UUID.randomUUID(),batchId=UUID.randomUUID(),operation=UUID.randomUUID();
    final String snapshot="a".repeat(64),moduleHash="b".repeat(64);
    NativeCompilationSnapshot snapshot(){var env=new NativeCompatibilityPolicy.Environment("26.1.2","neoforge","26.1.2.106","official",25,"TEST",Map.of());return new NativeCompilationSnapshot(1,"official","SERVER","RAW_MODULE_RESOURCES_NOT_LIVE_TRANSFORMS",env,List.of(new NativeCompilationSnapshot.Module("minecraft","1",moduleHash,1,1)),1,1);}
    WorldActionSpec action(String snap)throws Exception{return WorldActionSpec.parse(List.of(Map.of("id","members","name","inspect_native_members","arguments","{\"snapshot\":\""+snap+"\",\"module\":\"minecraft\",\"class\":\"net.minecraft.server.MinecraftServer\",\"query\":\"\",\"offset\":0,\"text_offset\":0}"))).getFirst();}
    WorldActionJournal.Batch batch(boolean verified,String snap)throws Exception{var action=action(snap);var receipt=new WorldActionJournal.Receipt(operation,0,action.tool(),verified,verified?"":"FAILED",Map.of(),Map.of("snapshot",snap,"count","1","result","{}"));return new WorldActionJournal.Batch(batchId,world,task,1,agent,owner,"minecraft:overworld",List.of(action),1,"COMPLETED","",Map.of(),List.of(receipt),4,0,List.of(operation));}
    @Test void buildsSelectionOnlyFromExactVerifiedMemberReceipt()throws Exception{
        var source=snapshot();var context=NativeGenerationContext.resolve(List.of(batch(true,snapshot)),new NativeObservationSelection(List.of(operation)),source,snapshot,source.environment().fingerprint());
        assertEquals(snapshot,context.snapshot());assertEquals("minecraft",context.types().getFirst().module());assertEquals("net.minecraft.server.MinecraftServer",context.types().getFirst().className());
    }
    @Test void exactVerifiedMethodBodyReceiptAddsOnlyItsMethodSelector()throws Exception{
        String descriptor="(Ljava/util/function/BooleanSupplier;)V";UUID memberBatch=UUID.randomUUID(),memberOperation=UUID.randomUUID();var memberAction=action(snapshot);var memberReceipt=new WorldActionJournal.Receipt(memberOperation,0,memberAction.tool(),true,"",Map.of(),Map.of("snapshot",snapshot,"count","1","result","{\"methods\":[{\"name\":\"tickServer\",\"descriptor\":\""+descriptor+"\"}]}"));var members=new WorldActionJournal.Batch(memberBatch,world,task,1,agent,owner,"minecraft:overworld",List.of(memberAction),1,"COMPLETED","",Map.of(),List.of(memberReceipt),4,0,List.of(memberOperation));
        UUID id=UUID.randomUUID(),op=UUID.randomUUID();var action=WorldActionSpec.parse(List.of(Map.of("id","body","name","inspect_native_method_body","arguments","{\"snapshot\":\""+snapshot+"\",\"module\":\"minecraft\",\"class\":\"net.minecraft.server.MinecraftServer\",\"method\":\"tickServer\",\"descriptor\":\""+descriptor+"\"}"))).getFirst();var receipt=new WorldActionJournal.Receipt(op,0,action.tool(),true,"",Map.of(),Map.of("snapshot",snapshot,"count","64","result","{}"));var batch=new WorldActionJournal.Batch(id,world,task,1,agent,owner,"minecraft:overworld",List.of(action),1,"COMPLETED","",Map.of(),List.of(receipt),4,1,List.of(op));
        var source=snapshot();var context=NativeGenerationContext.resolve(List.of(members,batch),new NativeObservationSelection(List.of(op)),source,snapshot,source.environment().fingerprint());assertEquals(1,context.types().size());assertEquals(1,context.methods().size());assertEquals("tickServer",context.methods().getFirst().name());
    }
    @Test void exactSourceReceiptRequiresPriorClassObservationAndBindsSourceSelector()throws Exception{
        var members=batch(true,snapshot);UUID id=UUID.randomUUID(),op=UUID.randomUUID();var action=WorldActionSpec.parse(List.of(Map.of("id","source","name","inspect_native_source","arguments","{\"snapshot\":\""+snapshot+"\",\"module\":\"minecraft\",\"class\":\"net.minecraft.server.MinecraftServer\"}"))).getFirst();var receipt=new WorldActionJournal.Receipt(op,0,action.tool(),true,"",Map.of(),Map.of("snapshot",snapshot,"count","16","result","{}"));var sourceBatch=new WorldActionJournal.Batch(id,world,task,1,agent,owner,"minecraft:overworld",List.of(action),1,"COMPLETED","",Map.of(),List.of(receipt),4,1,List.of(op));var nativeSnapshot=snapshot();var context=NativeGenerationContext.resolve(List.of(members,sourceBatch),new NativeObservationSelection(List.of(op)),nativeSnapshot,snapshot,nativeSnapshot.environment().fingerprint());assertEquals(1,context.sources().size());assertTrue(context.sources().getFirst().method().isEmpty());assertThrows(IllegalStateException.class,()->NativeGenerationContext.resolve(List.of(sourceBatch),new NativeObservationSelection(List.of(op)),nativeSnapshot,snapshot,nativeSnapshot.environment().fingerprint()));var methodSource=NativeApiToolRequest.parse("inspect_native_source","{\"snapshot\":\""+snapshot+"\",\"module\":\"minecraft\",\"class\":\"net.minecraft.server.MinecraftServer\",\"method\":\"tickServer\",\"descriptor\":\"(Ljava/util/function/BooleanSupplier;)V\"}");assertThrows(IllegalStateException.class,()->NativeSourceObservation.require(List.of(members),methodSource));
    }
    @Test void transformedReceiptBindsFrozenOverlayAndProcessEpoch()throws Exception{
        UUID id=UUID.randomUUID(),op=UUID.randomUUID();String classHash="c".repeat(64),rawHash="d".repeat(64),epoch=UUID.randomUUID().toString();var action=WorldActionSpec.parse(List.of(Map.of("id","transformed","name","inspect_native_transformed_members","arguments","{\"snapshot\":\""+snapshot+"\",\"module\":\"minecraft\",\"class\":\"net.minecraft.server.MinecraftServer\",\"query\":\"tick\"}"))).getFirst();String result="{\"provenance\":\"FML_TRANSFORM_PIPELINE_PREDEFINE\",\"class\":\"net.minecraft.server.MinecraftServer\",\"classRef\":\""+classHash+"\",\"classHash\":\""+classHash+"\",\"rawClassHash\":\""+rawHash+"\",\"processEpoch\":\""+epoch+"\",\"module\":\"minecraft\",\"loader\":\"TransformingClassLoader\",\"audit\":\"mixin:x\",\"methods\":[]}";var receipt=new WorldActionJournal.Receipt(op,0,action.tool(),true,"",Map.of(),Map.of("snapshot",snapshot,"count","1","result",result));var batch=new WorldActionJournal.Batch(id,world,task,1,agent,owner,"minecraft:overworld",List.of(action),1,"COMPLETED","",Map.of(),List.of(receipt),2,0,List.of(op));var source=snapshot();var context=NativeGenerationContext.resolve(List.of(batch),new NativeObservationSelection(List.of(op)),source,snapshot,source.environment().fingerprint(),epoch);assertTrue(context.types().isEmpty());assertEquals(1,context.overlays().size());assertEquals("FML_TRANSFORM_PIPELINE_PREDEFINE",context.overlays().getFirst().provenance());assertThrows(IllegalStateException.class,()->NativeGenerationContext.resolve(List.of(batch),new NativeObservationSelection(List.of(op)),source,snapshot,source.environment().fingerprint(),UUID.randomUUID().toString()));
    }
    @Test void rejectsMissingUnverifiedMixedAndStaleObservations()throws Exception{
        var source=snapshot();assertThrows(IllegalStateException.class,()->NativeGenerationContext.resolve(List.of(batch(false,snapshot)),new NativeObservationSelection(List.of(operation)),source,snapshot,source.environment().fingerprint()));
        assertThrows(IllegalStateException.class,()->NativeGenerationContext.resolve(List.of(batch(true,snapshot)),new NativeObservationSelection(List.of(UUID.randomUUID())),source,snapshot,source.environment().fingerprint()));
        assertThrows(IllegalStateException.class,()->NativeGenerationContext.resolve(List.of(batch(true,snapshot)),new NativeObservationSelection(List.of(operation)),source,"c".repeat(64),source.environment().fingerprint()));
        UUID otherBatch=UUID.randomUUID(),otherOperation=UUID.randomUUID();var otherAction=action("c".repeat(64));var otherReceipt=new WorldActionJournal.Receipt(otherOperation,0,otherAction.tool(),true,"",Map.of(),Map.of("snapshot","c".repeat(64),"count","1","result","{}"));var mixed=new WorldActionJournal.Batch(otherBatch,world,task,1,agent,owner,"minecraft:overworld",List.of(otherAction),1,"COMPLETED","",Map.of(),List.of(otherReceipt),4,1,List.of(otherOperation));
        assertThrows(IllegalStateException.class,()->NativeGenerationContext.resolve(List.of(batch(true,snapshot),mixed),new NativeObservationSelection(List.of(operation,otherOperation)),source,snapshot,source.environment().fingerprint()));
        var valid=batch(true,snapshot);var receipt=new WorldActionJournal.Receipt(UUID.randomUUID(),0,"inspect_native_members",true,"",Map.of(),Map.of("snapshot",snapshot,"count","1","result","{}"));assertThrows(IllegalArgumentException.class,()->new WorldActionJournal.Batch(valid.batchId(),valid.worldId(),valid.taskId(),valid.intent(),valid.agentId(),valid.owner(),valid.dimension(),valid.actions(),valid.cursor(),valid.state(),valid.error(),valid.before(),List.of(receipt),valid.revision(),valid.round(),valid.operationIds()));
    }
}
